#include "StreamlineRuntime.h"
#include <d3dcompiler.h>
#include <vector>
#include <iostream>
#include <algorithm>
#include <DirectXPackedVector.h>
void transition(ID3D12GraphicsCommandList*l,ID3D12Resource*r,D3D12_RESOURCE_STATES a,D3D12_RESOURCE_STATES b){if(a==b)return;D3D12_RESOURCE_BARRIER barrier{};barrier.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;barrier.Transition={r,D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES,a,b};l->ResourceBarrier(1,&barrier);}
#include "OpticalMotion.h"
int main(int argc,char**argv){try{const int test=0; if(argc!=3)throw std::runtime_error("Pass packet folder and output prefix"); const std::string packet=argv[1],prefix=argv[2]; const unsigned W=2560,H=1440;const int dx=test==1?-6:8,dy=test==1?4:0,panX=test==2?5:0,panY=test==2?-3:0;
 rtx::ComPtr<IDXGIFactory1> factory;rtx::check(CreateDXGIFactory1(IID_PPV_ARGS(&factory)),"factory");rtx::ComPtr<IDXGIAdapter1> adapter;for(unsigned i=0;;++i){rtx::ComPtr<IDXGIAdapter1>a;if(factory->EnumAdapters1(i,&a)==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 d{};a->GetDesc1(&d);if(d.VendorId==0x10de){adapter=a;break;}}
 rtx::ComPtr<ID3D12Device> device;rtx::check(D3D12CreateDevice(adapter.Get(),D3D_FEATURE_LEVEL_12_0,IID_PPV_ARGS(&device)),"device");rtx::ComPtr<ID3D12CommandQueue> queue;D3D12_COMMAND_QUEUE_DESC q{};rtx::check(device->CreateCommandQueue(&q,IID_PPV_ARGS(&queue)),"queue");opticalmotion::Engine engine;engine.init(device.Get(),queue.Get(),W,H);
 const unsigned scale=test==4?2:1;auto color=engine.texture(DXGI_FORMAT_R8G8B8A8_UNORM,D3D12_RESOURCE_FLAG_NONE),camera=engine.texture(DXGI_FORMAT_R16G16_FLOAT,D3D12_RESOURCE_FLAG_NONE),depth=engine.texture(DXGI_FORMAT_R32_FLOAT,D3D12_RESOURCE_FLAG_NONE);if(scale==2){auto d=color->GetDesc();d.Width*=2;d.Height*=2;color.Reset();D3D12_HEAP_PROPERTIES hp{};hp.Type=D3D12_HEAP_TYPE_DEFAULT;rtx::check(device->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&d,D3D12_RESOURCE_STATE_COMMON,nullptr,IID_PPV_ARGS(&color)),"high resolution scene");}
 rtx::ComPtr<ID3D12CommandAllocator> allocator;device->CreateCommandAllocator(q.Type,IID_PPV_ARGS(&allocator));rtx::ComPtr<ID3D12GraphicsCommandList> list;device->CreateCommandList(0,q.Type,allocator.Get(),nullptr,IID_PPV_ARGS(&list));list->Close();rtx::ComPtr<ID3D12Fence> fence;device->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&fence));auto event=CreateEventW(nullptr,FALSE,FALSE,nullptr);UINT64 marker=0;
 auto submit=[&](){rtx::check(list->Close(),"close");ID3D12CommandList* lists[]{list.Get()};queue->ExecuteCommandLists(1,lists);queue->Signal(fence.Get(),++marker);fence->SetEventOnCompletion(marker,event);if(WaitForSingleObject(event,10000)!=WAIT_OBJECT_0)throw std::runtime_error("bounded GPU test timeout");};
 auto begin=[&](){rtx::check(allocator->Reset(),"allocator reset");rtx::check(list->Reset(allocator.Get(),nullptr),"list reset");};
 std::vector<rtx::ComPtr<ID3D12Resource>> uploads;
 auto upload=[&](ID3D12Resource* target,const void* data){auto d=target->GetDesc();D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp{};UINT64 size{};device->GetCopyableFootprints(&d,0,1,0,&fp,nullptr,nullptr,&size);D3D12_HEAP_PROPERTIES heap{};heap.Type=D3D12_HEAP_TYPE_UPLOAD;D3D12_RESOURCE_DESC buffer{};buffer.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;buffer.Width=size;buffer.Height=1;buffer.DepthOrArraySize=buffer.MipLevels=1;buffer.SampleDesc.Count=1;buffer.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;rtx::ComPtr<ID3D12Resource> u;rtx::check(device->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&buffer,D3D12_RESOURCE_STATE_GENERIC_READ,nullptr,IID_PPV_ARGS(&u)),"upload");void* p{};u->Map(0,nullptr,&p);for(unsigned y=0;y<d.Height;++y)memcpy((char*)p+y*fp.Footprint.RowPitch,(char*)data+y*d.Width*4,d.Width*4);u->Unmap(0,nullptr);transition(list.Get(),target,D3D12_RESOURCE_STATE_COMMON,D3D12_RESOURCE_STATE_COPY_DEST);D3D12_TEXTURE_COPY_LOCATION dst{};dst.pResource=target;dst.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;D3D12_TEXTURE_COPY_LOCATION src{};src.pResource=u.Get();src.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;src.PlacedFootprint=fp;list->CopyTextureRegion(&dst,0,0,0,&src,nullptr);transition(list.Get(),target,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_COMMON);uploads.push_back(u);};
 std::vector<unsigned> pixels(W*H),cameraBytes(W*H);std::vector<float> z(W*H);
 auto readFile=[&](const char* name,void* data,size_t bytes){std::ifstream in(packet+"/"+name,std::ios::binary);if(!in.read((char*)data,bytes))throw std::runtime_error("Truncated captured input");};
 readFile("06-camera-motion.bin",cameraBytes.data(),W*H*4);readFile("08-depth.bin",z.data(),W*H*4);
 begin();upload(camera.Get(),cameraBytes.data());upload(depth.Get(),z.data());submit();ID3D12Resource* result{};
 for(unsigned f=0;f<2;++f){std::vector<unsigned char> luma(W*H);readFile(f?"05-current-estimation-luma.bin":"04-previous-estimation-luma.bin",luma.data(),luma.size());for(unsigned i=0;i<W*H;++i)pixels[i]=0xff000000u|unsigned(luma[i])*0x010101u;
 begin();upload(color.Get(),pixels.data());submit();begin();transition(list.Get(),camera.Get(),D3D12_RESOURCE_STATE_COMMON,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);transition(list.Get(),depth.Get(),D3D12_RESOURCE_STATE_COMMON,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);result=engine.record(list.Get(),color.Get(),D3D12_RESOURCE_STATE_COMMON,camera.Get(),depth.Get(),false,f);transition(list.Get(),camera.Get(),D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COMMON);transition(list.Get(),depth.Get(),D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COMMON);submit();}
 auto save=[&](ID3D12Resource* result,const std::string& name){
 if(!result)throw std::runtime_error("No estimated motion");D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp{};UINT64 size{};auto desc=result->GetDesc();device->GetCopyableFootprints(&desc,0,1,0,&fp,nullptr,nullptr,&size);D3D12_HEAP_PROPERTIES heap{};heap.Type=D3D12_HEAP_TYPE_READBACK;D3D12_RESOURCE_DESC rd{};rd.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;rd.Width=size;rd.Height=1;rd.DepthOrArraySize=rd.MipLevels=1;rd.SampleDesc.Count=1;rd.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;rtx::ComPtr<ID3D12Resource> read;rtx::check(device->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&rd,D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&read)),"readback");begin();transition(list.Get(),result,D3D12_RESOURCE_STATE_COMMON,D3D12_RESOURCE_STATE_COPY_SOURCE);D3D12_TEXTURE_COPY_LOCATION src{},dst{};src.pResource=result;src.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;dst.pResource=read.Get();dst.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;dst.PlacedFootprint=fp;list->CopyTextureRegion(&dst,0,0,0,&src,nullptr);transition(list.Get(),result,D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_COMMON);submit();void* mapped{};read->Map(0,nullptr,&mapped);{std::ofstream raw(name,std::ios::binary);for(unsigned y=0;y<H;++y)raw.write((char*)mapped+y*fp.Footprint.RowPitch,W*4);}read->Unmap(0,nullptr);};
 save(result,prefix+"-resolved.bin");save(engine.forward.Get(),prefix+"-forward.bin");save(engine.backward.Get(),prefix+"-backward.bin");CloseHandle(event);std::cout<<"Captured pair replay complete\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
